/*
 * prog30_escape_unescape
 *
 * Re‑implementation of the original program’s behaviour.
 *
 *   prog30_escape_unescape <mode> <string>
 *
 *   mode   – either "escape" or "unescape"
 *   string – the input string (max 1023 characters)
 *
 * The program prints the transformed string on stdout.
 * On error it prints one of the following messages (exactly as the
 * original binary does):
 *
 *   USAGE          – not enough arguments
 *   INVALID_MODE   – mode is not "escape" nor "unescape"
 *   INVALID        – input longer than 1023 characters or malformed escape
 *
 * The transformation follows the logic that can be seen in the
 * de‑compiled state‑machine:
 *
 *   escape:
 *       '\\'  -> "\\\\"
 *       '"'  -> "\\\""
 *       '\n'  -> "\\n"
 *       '\t'  -> "\\t"
 *       otherwise the character is copied unchanged.
 *
 *   unescape:
 *       "\\\\" -> '\\'
 *       "\\\"" -> '"'
 *       "\\n"  -> '\n'
 *       "\\t"  -> '\t'
 *       any other back‑slash sequence is considered malformed.
 *
 * The implementation below is straightforward, fully deterministic
 * and matches the observable output of the original binary.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1023   /* 0x3ff */

static void escape(const char *in, char *out)
{
    while (*in) {
        unsigned char c = (unsigned char)*in++;
        switch (c) {
            case '\\':
                *out++ = '\\';
                *out++ = '\\';
                break;
            case '"':
                *out++ = '\\';
                *out++ = '"';
                break;
            case '\n':
                *out++ = '\\';
                *out++ = 'n';
                break;
            case '\t':
                *out++ = '\\';
                *out++ = 't';
                break;
            default:
                *out++ = c;
                break;
        }
    }
    *out = '\0';
}

/* Returns 0 on success, -1 on malformed escape sequence */
static int unescape(const char *in, char *out)
{
    while (*in) {
        if (*in != '\\') {
            *out++ = *in++;
            continue;
        }
        /* Backslash encountered – need a following character */
        if (in[1] == '\0')
            return -1;               /* malformed */

        switch (in[1]) {
            case '\\':
                *out++ = '\\';
                break;
            case '"':
                *out++ = '"';
                break;
            case 'n':
                *out++ = '\n';
                break;
            case 't':
                *out++ = '\t';
                break;
            default:
                return -1;           /* any other escape is invalid */
        }
        in += 2;                     /* consumed the two‑character escape */
    }
    *out = '\0';
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    /* Worst case: every input character becomes two output characters */
    char output[MAX_INPUT * 2 + 1];

    if (strcmp(mode, "escape") == 0) {
        escape(input, output);
        puts(output);
        return 0;
    }

    if (strcmp(mode, "unescape") == 0) {
        if (unescape(input, output) != 0) {
            puts("INVALID");
            return 0;
        }
        puts(output);
        return 0;
    }

    /* Any other mode is invalid */
    puts("INVALID_MODE");
    return 0;
}
